#include "build-info.h"

#include "llama.h"

#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>

// embedded data generated by cmake
extern const char * LICENSES[];

// visible
int llama_server(int argc, char ** argv);
int llama_cli(int argc, char ** argv);

// hidden
int llama_completion(int argc, char ** argv);
int llama_bench(int argc, char ** argv);
int llama_batched_bench(int argc, char ** argv);
int llama_fit_params(int argc, char ** argv);
int llama_quantize(int argc, char ** argv);
int llama_perplexity(int argc, char ** argv);
int llama_download(int argc, char ** argv);

// Self-update is only supported for binaries built with llama-install.sh.
// A source build instead reports how the installed binary compares to the
// source tree and to upstream, and prints the commands to catch up. It never
// auto-rebuilds: this is a manual, experimental setup.
static int llama_update(int argc, char ** argv) {
    (void) argc;
    (void) argv;

#ifdef LLAMA_INSTALL_BUILD
#if defined(_WIN32)
    return system("powershell -NoProfile -ExecutionPolicy Bypass -Command \"irm https://llama.app/install.ps1 | iex\"");
#else
    return system("curl -fsSL https://llama.app/install.sh | sh");
#endif
#else
     const char * src_dir = std::getenv("LLAMA_SRC_DIR");
     if (!src_dir || !*src_dir) {
     printf("LLAMA_SRC_DIR is not set; point it at your llama.cpp source dir\n");
     return 1;
     }

     const std::string embedded = llama_commit();
     const std::string cmd_cd   = "cd '" + std::string(src_dir) + "'";

     if (system((cmd_cd + " && git fetch origin master 2>&1").c_str()) != 0) {
     printf("warning: git fetch failed (offline or not a git checkout);\n");
     printf("            comparing against the last known remote state\n\n");
     }

     auto rev = [&](const char * ref) -> std::string {
     std::string cmd = cmd_cd + " && git rev-parse --short " + std::string(ref);
     std::string out;
     FILE * fp = popen(cmd.c_str(), "r");
     if (!fp) {
          return {};
     }
     char buf[64];
     while (fgets(buf, sizeof buf, fp)) {
          out += buf;
     }
     pclose(fp);
     while (!out.empty() && (out.back() == '\n' || out.back() == '\r')) {
          out.pop_back();
     }
     return out;
     };

     const std::string head        = rev("HEAD");
     const std::string upstream    = rev("origin/master");
     // we carry local commits, so "up to date" = origin/master is an ANCESTOR of HEAD
     const bool behind_upstream =
     system((cmd_cd + " && git merge-base --is-ancestor origin/master HEAD 2>/dev/null").c_str()) != 0;
     // the installed commit may be longer than HEAD's 7 chars; prefix-compare
     const bool installed_current =
     embedded.size() >= 7 && embedded.compare(0, 7, head.substr(0, 7)) == 0;

     printf("installed build : %s (build %d)\n", embedded.c_str(), llama_build_number());
     if (head.empty()) {
     printf("local source       : unknown (git not available?)\n\n");
     printf("this binary is a source build, not a llama.app install.\n");
     printf("To update: pull the source and rebuild (see build-setup/README.md).\n");
     return 2;
     }
     printf("local source       : %s\n", head.c_str());
     printf("upstream master    : %s\n", upstream.empty() ? "unknown (fetch failed?)" : upstream.c_str());
     printf("\n");

     bool outdated = false;
     if (!installed_current) {
     outdated = true;
     printf("-> the installed build is older than your local source. Rebuild it:\n");
     printf("          cmake --build build --config Release -j$(nproc)\n");
     printf("          cmake --install build --prefix \"$HOME/.local\" && llama-reinstall\n");
     }
     if (behind_upstream) {
     outdated = true;
     printf("-> upstream is ahead of your local source. To update:\n");
     printf("          git -C '%s' fetch origin && git -C '%s' rebase origin/master\n", src_dir, src_dir);
     printf("          cmake --build build --config Release -j$(nproc)\n");
     printf("          cmake --install build --prefix \"$HOME/.local\" && llama-reinstall\n");
     }
     if (!outdated) {
     printf("up to date.\n");
     }
     return outdated ? 2 : 0;
#endif
}

static const char * progname;

static int help(int argc, char ** argv);
static int version(int argc, char ** argv);
static int licenses(int argc, char ** argv);

struct command {
    const char * name;
    const char * desc;
    std::vector<std::string> aliases;
    bool hidden;
    int (*func)(int, char **);
    bool flags = false; // allow --name
};

#ifdef LLAMA_INSTALL_BUILD
#define UPDATE_HIDDEN false
#else
#define UPDATE_HIDDEN true
#endif

static const command cmds[] = {
    {"serve",         "HTTP API server",                                    {"server"},   false,         llama_server       },
    {"cli",           "Command-line interactive interface",                 {"client"},   false,         llama_cli          },
    {"update",        "Update llama to the latest release",                 {},           UPDATE_HIDDEN, llama_update       },
    {"download",      "Download a model",                                   {"get"},      false,         llama_download     },
    {"completion",    "Text completion",                                    {"complete"}, true,          llama_completion   },
    {"bench",         "Benchmark prompt processing and text generation",    {},           true,          llama_bench        },
    {"batched-bench", "Benchmark batched decoding performance",             {},           true,          llama_batched_bench},
    {"fit-params",    "Compute parameters to fit a model in device memory", {},           true,          llama_fit_params   },
    {"quantize",      "Quantize a model",                                   {},           true,          llama_quantize     },
    {"perplexity",    "Compute model perplexity and KL divergence",         {},           true,          llama_perplexity   },
    {"version",       "Show version",                                       {},           false,         version,           true },
    {"licenses",      "Show third-party licenses",                          {"credits"},  false,         licenses,          true },
    {"help",          "Show available commands",                            {},           false,         help,              true },
};

#undef UPDATE_HIDDEN

static int version(int /*argc*/, char ** /*argv*/) {
    llama_print_build_info(llama_version(), stdout);
    return 0;
}

static int licenses(int /*argc*/, char ** /*argv*/) {
    for (int i = 0; LICENSES[i]; ++i) {
        printf("%s\n", LICENSES[i]);
    }
    return 0;
}

static int help(int argc, char ** argv) {
    const bool show_all = argc >= 2 && std::string(argv[1]) == "all";

    printf("Usage: %s <command> [options]\n\nAvailable commands:\n", progname);

    for (const auto & cmd : cmds) {
        if (show_all || !cmd.hidden) {
            printf("  %-15s %s\n", cmd.name, cmd.desc);
        }
    }
    printf("\n");

    if (!show_all) {
        printf("Run '%s help all' to show additional commands.\n", progname);
    }
    printf("Run '%s <command> --help' for command-specific usage.\n", progname);

    return 0;
}

static bool matches(std::string arg, const command & cmd) {
    if (cmd.flags && arg.size() > 2 && arg[0] == '-' && arg[1] == '-') {
        arg.erase(0, 2);
    }
    if (arg == cmd.name) {
        return true;
    }
    for (const auto & alias : cmd.aliases) {
        if (arg == alias) {
            return true;
        }
    }
    return false;
}

int main(int argc, char ** argv) {
    progname = argv[0];

    const std::string arg = argc >= 2 ? argv[1] : "help";

    for (const auto & cmd : cmds) {
        if (matches(arg, cmd)) {
            // keep cmd.name so the router's child processes re-invoke correctly
#ifdef _WIN32
            _putenv_s("LLAMA_APP_CMD", cmd.name);
#else
            setenv("LLAMA_APP_CMD", cmd.name, 1);
#endif
            return cmd.func(argc - 1, argv + 1);
        }
    }

    fprintf(stderr, "error: unknown command '%s'\n", arg.c_str());
    return 1;
}
